-- TEST 083 only: recurring operator attribution and pause handling; no secrets or capture activation.
begin;
set local search_path=public,pg_catalog;set local lock_timeout='3s';set local statement_timeout='30s';
lock table of_test_deploy.migrations in share row exclusive mode;
do $$begin
 if current_setting('serviceos.release_target',true) is distinct from 'saatxzwxvdvqevbnskxy'
 or coalesce(current_setting('serviceos.release_source_sha256',true),'')!~'^[a-f0-9]{64}$'
 or (select md5(coalesce(string_agg(jsonb_build_object('definition',pg_get_functiondef(p.oid),'owner',r.rolname,'acl',p.proacl)::text,'' order by p.proname,pg_get_function_identity_arguments(p.oid)),'')) fingerprint from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_roles r on r.oid=p.proowner where n.nspname='public' and p.prokind in('f','p')) is distinct from '91bfd6d2a42d0ac2d24d9ec6c3276e5d'
 or (select count(*)::int active from public.platform_jobs where job_type in('slack.history_sync','slack.thread_sync') and status in('queued','running','retrying'))<>0 or not (select to_regprocedure('public.learn_slack_recurring_attribution_allowed(text,jsonb)') is null and to_regprocedure('public.learn_slack_reference_guard()') is not null absent) then raise exception 'Slack TEST release precondition changed';end if;
end$$;
